[hidden] { display: none !important; }
:root { color-scheme: light; --ink: #24352e; --muted: #65756c; --paper: #fffdf7; --green: #245c49; --mint: #e5f1e9; --gold: #e7b85c; }
* { box-sizing: border-box; }
body { min-height: 100vh; margin: 0; padding: 32px 16px; display: grid; place-items: center; background-color: #dce9df; background-image: radial-gradient(#b9d0bd 1.5px, transparent 1.5px); background-size: 22px 22px; color: var(--ink); font: 16px/1.5 system-ui, sans-serif; }
.shop { width: min(100%, 560px); padding: 32px; border: 2px solid var(--ink); border-radius: 18px; background: var(--paper); box-shadow: 8px 8px 0 var(--ink); }
.shop-header { text-align: center; }
.shop-mark { width: 54px; height: 54px; margin: 0 auto 10px; display: grid; place-items: center; border: 2px solid var(--ink); border-radius: 12px; background: var(--gold); font-size: 30px; }
.eyebrow { margin: 0; color: var(--green); font-size: 13px; font-weight: 800; letter-spacing: .12em; }
h1 { margin: 2px 0 0; font-size: clamp(32px, 8vw, 42px); line-height: 1.2; letter-spacing: -.04em; }
.intro { margin: 8px 0 22px; color: var(--muted); }
.sales-panel { display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 16px 18px; border: 2px solid var(--ink); border-radius: 12px; background: var(--mint); font-weight: 700; }
.sales-panel strong { color: var(--green); font-size: 25px; font-variant-numeric: tabular-nums; }
.inventory { margin-top: 25px; }
h2 { display: flex; align-items: baseline; justify-content: space-between; gap: 8px; margin: 0 0 12px; font-size: 20px; }
h2 span { color: var(--muted); font-size: 14px; font-weight: 600; }
.item-list { display: grid; gap: 10px; }
.item { display: grid; grid-template-columns: 44px minmax(0, 1fr) auto; align-items: center; gap: 12px; padding: 12px; border: 1.5px solid #d3ddd4; border-radius: 12px; background: #fff; }
.item-icon { width: 44px; height: 44px; display: grid; place-items: center; border-radius: 10px; background: var(--mint); font-size: 25px; }
.item-name { display: block; font-weight: 750; }
.item-meta { display: block; color: var(--muted); font-size: 14px; }
.item-meta.sold { color: #9a573c; font-weight: 750; }
.actions { display: flex; gap: 7px; }
button { min-height: 42px; padding: 8px 12px; border: 2px solid var(--ink); border-radius: 9px; background: var(--green); color: white; font: inherit; font-weight: 750; cursor: pointer; transition: transform .12s, background-color .12s, box-shadow .12s; }
button:hover:not(:disabled) { background: #174333; box-shadow: 0 3px 0 var(--ink); transform: translateY(-1px); }
button:active:not(:disabled) { box-shadow: none; transform: translateY(1px); }
button:focus-visible { outline: 3px solid var(--gold); outline-offset: 3px; }
button:disabled { border-color: #cbd3cc; background: #e6eae6; color: #737d75; cursor: not-allowed; }
button.restock { background: var(--paper); color: var(--ink); }
button.restock:hover { background: var(--mint); }
footer { margin-top: 20px; color: var(--muted); text-align: center; font-size: 14px; }
@media (max-width: 440px) { body { padding: 18px 12px; } .shop { padding: 22px 16px; box-shadow: 5px 5px 0 var(--ink); } .item { grid-template-columns: 40px minmax(0, 1fr); gap: 10px; } .item-icon { width: 40px; height: 40px; } .actions { grid-column: 1 / -1; justify-content: stretch; } .actions button { flex: 1; } }

const items = [
  { name: 'Mushroom Lamp', icon: '🍄', price: 18, stock: 4 },
  { name: 'Tiny Cactus', icon: '🌵', price: 12, stock: 6 },
  { name: 'Moon Mug', icon: '🌙', price: 15, stock: 3 },
  { name: 'Star Plush', icon: '⭐', price: 24, stock: 2 },
  { name: 'Berry Jam', icon: '🫐', price: 9, stock: 5 }
];
let sales = 0;
const itemList = document.querySelector('#item-list');
const salesTotal = document.querySelector('#sales-total');
const money = amount => `$${amount.toFixed(2)}`;

function render() {
  itemList.replaceChildren();
  items.forEach((item, index) => {
    const row = document.createElement('article');
    row.className = 'item';
    const icon = document.createElement('span');
    icon.className = 'item-icon';
    icon.setAttribute('aria-hidden', 'true');
    icon.textContent = item.icon;
    const details = document.createElement('div');
    const name = document.createElement('span');
    name.className = 'item-name';
    name.textContent = item.name;
    const meta = document.createElement('span');
    meta.className = `item-meta${item.stock === 0 ? ' sold' : ''}`;
    meta.textContent = item.stock === 0 ? `${money(item.price)} · Sold out` : `${money(item.price)} · ${item.stock} in stock`;
    details.append(name, meta);
    const actions = document.createElement('div');
    actions.className = 'actions';
    const sell = document.createElement('button');
    sell.type = 'button';
    sell.textContent = 'Sell';
    sell.setAttribute('aria-label', `Sell ${item.name}`);
    sell.disabled = item.stock === 0;
    sell.addEventListener('click', () => {
      if (item.stock > 0) { item.stock--; sales += item.price; render(); }
    });
    const restock = document.createElement('button');
    restock.type = 'button';
    restock.className = 'restock';
    restock.textContent = 'Restock +10';
    restock.setAttribute('aria-label', `Restock ${item.name} by 10`);
    restock.addEventListener('click', () => { item.stock += 10; render(); });
    actions.append(sell, restock);
    row.append(icon, details, actions);
    itemList.append(row);
  });
  salesTotal.textContent = money(sales);
}

render();
